28	/**
29	 * A token is usable only when it is a real credential. The setup-node
30	 * placeholder and an unexpanded `${NODE_AUTH_TOKEN}` are both unusable.
31	 * @param {string|undefined} token
32	 * @returns {boolean}
33	 */
34	export function isUsableToken(token) {
35	  const value = String(token ?? '').trim();
36	  if (value === '') return false;
37	  if (value === SETUP_NODE_PLACEHOLDER_TOKEN) return false;
38	  if (/^\$\{?NODE_AUTH_TOKEN\}?$/.test(value)) return false;
39	  return true;
